lines=['# AVENIQ Feature-Matrix – Outlook-Parität & Nutzerwünsche','','**Legende:** `I` = **implementiert und lokal getestet**, `P` = **teilweise** (stets Einschränkungen prüfen), `N` = **nicht implementiert** / Roadmap. Statusbezeichnungen beziehen sich auf **v0.1**, nicht auf ein abgeschlossenes Outlook-Äquivalent. `P0` = Kernfunktion, `P1` = wichtige Erweiterung, `P2` = Team/Pro, `P3` = Enterprise.','','Die vollständigen Journeys, Qualitätsziele, Userfeedback-Hypothesen und Sicherheitshinweise stehen in [`PRODUCT_SPEC.md`](PRODUCT_SPEC.md), [`USER_FEEDBACK.md`](USER_FEEDBACK.md) und [`ROADMAP.md`](ROADMAP.md).','']
counts={'I':0,'P':0,'N':0}
i=0
for section,text in sections.items():
 lines.extend(['## '+section,'','| ID | Feature | Status v0.1 | Priorität |','|---|---|---|---|'])
 for part in text.split(';'):
  name,status,pr=part.strip().split('|');i+=1;counts[status]+=1
  lines.append(f'| FD-{i:03d} | {name} | **{status}** | {pr} |')
 lines.append('')
lines[3]+=f' **Umfang:** {i} einzelne Anforderungen; {counts["I"]} implementiert, {counts["P"]} teilweise, {counts["N"]} offen.'
lines+=['## Definition of done','', 'Ein Feature ist erst implementiert, wenn API + UI + Fehlerszenarien + automatisierter Test + Datenschutz-/Rechteeinordnung vorliegen. Ohne Provider-Livetest ist die Unterstützung des Providers stets eingeschränkt zu kennzeichnen. Ein visuelles Mockup ist kein Funktionsbeweis.','','`I` bezieht sich auf lokale Implementierung und interne Tests (wo vorhanden), nicht auf vollständige E-Mail-/Kalenderprovider-Interoperabilität.']
Path(__file__).with_name('FEATURE_MATRIX.md').write_text('\n'.join(lines)+'\n')
print(i,counts)
